return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2015-08-14 00:59:42+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Movable Type and TypePad Importer - Stable (latest release)','language'=>'en_CA','messages'=>['http://wordpress.org/'=>'http://en-ca.wordpress.org/','wordpressdotorg'=>'wordpressdotorg','http://wordpress.org/extend/plugins/movabletype-importer/'=>'https://wordpress.org/plugins/movabletype-importer/','Movable Type and TypePad Importer'=>'Movable Type and TypePad Importer','Import posts and comments from a Movable Type or TypePad blog.'=>'Import posts and comments from a Movable Type or TypePad blog.','Movable Type and TypePad'=>'Movable Type and TypePad','All done. <a href="%s">Have fun!</a>'=>'All done. <a href="%s">Have fun!</a>','(%s ping)'=>'(%s ping)' . "\0" . '(%s pings)','(%s comment)'=>'(%s comment)' . "\0" . '(%s comments)','Adding tags <em>%s</em>...'=>'Adding tags <em>%s</em>...','Importing post <em>%s</em>...'=>'Importing post <em>%s</em>...','Post <em>%s</em> already exists.'=>'Post <em>%s</em> already exists.','Sorry, there has been an error'=>'Sorry, there has been an error','<code>mt-export.txt</code> does not exist'=>'<code>mt-export.txt</code> does not exist','Submit'=>'Submit','Create user %1$s or map to existing'=>'Create user %1$s or map to existing','Current author:'=>'Current author:','If a new user is created by WordPress, a password will be randomly generated. Manually change the user&#8217;s details if necessary.'=>'If a new user is created by WordPress, a password will be randomly generated. Manually change the user&#8217;s details if necessary.','Below, you can see the names of the authors of the Movable Type posts in <em>italics</em>. For each of these names, you can either pick an author in your WordPress installation from the menu, or enter a name for the author in the textbox.'=>'Below, you can see the names of the authors of the Movable Type posts in <em>italics</em>. For each of these names, you can either pick an author in your WordPress installation from the menu, or enter a name for the author in the textbox.','To make it easier for you to edit and save the imported posts and drafts, you may want to change the name of the author of the posts. For example, you may want to import all the entries as admin&#8217;s entries.'=>'To make it easier for you to edit and save the imported posts and drafts, you may want to change the name of the author of the posts. For example, you may want to import all the entries as admin&#8217;s entries.','Assign Authors'=>'Assign Authors','&mdash; Select &mdash;'=>'&mdash; Select &mdash;','The importer is smart enough not to import duplicates, so you can run this multiple times without worry if&#8212;for whatever reason&#8212;it doesn&#8217;t finish. If you get an <strong>out of memory</strong> error try splitting up the import file into pieces.'=>'The importer is smart enough not to import duplicates, so you can run this multiple times without worry if&#8212;for whatever reason&#8212;it doesn&#8217;t finish. If you get an <strong>out of memory</strong> error try splitting up the import file into pieces.','Import mt-export.txt'=>'Import mt-export.txt','Or use <code>mt-export.txt</code> in your <code>/wp-content/</code> directory'=>'Or use <code>mt-export.txt</code> in your <code>/wp-content/</code> directory','Howdy! We are about to begin importing all of your Movable Type or TypePad entries into WordPress. To begin, either choose a file to upload and click &#8220;Upload file and import&#8221;, or use FTP to upload your MT export file as <code>mt-export.txt</code> in your <code>/wp-content/</code> directory and then click &#8220;Import mt-export.txt&#8221;.'=>'Howdy! We are about to begin importing all of your Movable Type or TypePad entries into WordPress. To begin, either choose a file to upload and click &#8220;Upload file and import&#8221;, or use FTP to upload your MT export file as <code>mt-export.txt</code> in your <code>/wp-content/</code> directory and then click &#8220;Import mt-export.txt&#8221;.','Import Movable Type or TypePad'=>'Import Movable Type or TypePad']];